import json
import numpy as np
import pandas as pd

DATA_FILE = "/home/chs/Work/tga_plot/eval/inputs_b/polymers.xlsx"
SHEET = "PET"

df = pd.read_excel(DATA_FILE, sheet_name=SHEET)
df.columns = [str(c).strip() for c in df.columns]

x_col = next(c for c in df.columns if "Temperature" in c)
weight_col = next(c for c in df.columns if "Weight" in c and "Deriv" not in c)
dtg_col = next(c for c in df.columns if "Deriv" in c)

x = pd.to_numeric(df[x_col], errors="coerce").to_numpy(dtype=float)
weight = pd.to_numeric(df[weight_col], errors="coerce").to_numpy(dtype=float)
dtg = pd.to_numeric(df[dtg_col], errors="coerce").to_numpy(dtype=float)

valid = np.isfinite(x) & np.isfinite(weight) & np.isfinite(dtg)
x, weight, dtg = x[valid], weight[valid], dtg[valid]

residue_idx = int(np.argmin(np.abs(x - 800)))
residue_temp = float(x[residue_idx])
residue = float(weight[residue_idx])

peak_candidates = np.flatnonzero(x > 150)
peak_idx = int(peak_candidates[np.argmax(-dtg[peak_candidates])])
peak_temp = float(x[peak_idx])
peak_value = float(-dtg[peak_idx])

option = {
    "title": {
        "text": "PET 열분해",
        "left": "center",
        "textStyle": {"fontFamily": "Noto Sans CJK KR"}
    },
    "tooltip": {"trigger": "axis"},
    "legend": {
        "data": ["Weight (%)", "-DTG (%/°C)"],
        "left": 12,
        "bottom": 12,
        "orient": "vertical",
        "textStyle": {"fontFamily": "Noto Sans CJK KR"}
    },
    "grid": {"left": 65, "right": 65, "top": 65, "bottom": 65},
    "xAxis": {
        "type": "value",
        "name": "Temperature (°C)",
        "nameLocation": "middle",
        "nameGap": 35,
        "axisLine": {"show": True},
        "axisTick": {"show": True},
        "axisLabel": {"show": True},
        "splitLine": {"show": True, "lineStyle": {"color": "#dddddd"}}
    },
    "yAxis": [
        {
            "type": "value",
            "name": "Weight (%)",
            "nameLocation": "middle",
            "nameGap": 45,
            "axisLine": {"show": True, "lineStyle": {"color": "#1f4e9c"}},
            "axisTick": {"show": True},
            "axisLabel": {"show": True},
            "splitLine": {"show": True, "lineStyle": {"color": "#dddddd"}}
        },
        {
            "type": "value",
            "name": "-DTG (%/°C)",
            "nameLocation": "middle",
            "nameGap": 45,
            "axisLine": {"show": True, "lineStyle": {"color": "#c0392b"}},
            "axisTick": {"show": True},
            "axisLabel": {"show": True},
            "splitLine": {"show": False}
        }
    ],
    "series": [
        {
            "name": "Weight (%)",
            "type": "line",
            "yAxisIndex": 0,
            "showSymbol": False,
            "data": [[float(a), float(b)] for a, b in zip(x, weight)],
            "lineStyle": {"color": "#1f4e9c", "width": 2},
            "markPoint": {
                "symbol": "circle",
                "symbolSize": 9,
                "itemStyle": {"color": "#1f4e9c"},
                "data": [{
                    "coord": [residue_temp, residue],
                    "name": f"Residue {residue:.2f}%",
                    "label": {
                        "show": True,
                        "formatter": f"Residue {residue:.2f}%",
                        "position": "top"
                    }
                }]
            }
        },
        {
            "name": "-DTG (%/°C)",
            "type": "line",
            "yAxisIndex": 1,
            "showSymbol": False,
            "data": [[float(a), float(-b)] for a, b in zip(x, dtg)],
            "lineStyle": {"color": "#c0392b", "width": 2},
            "markPoint": {
                "symbol": "circle",
                "symbolSize": 9,
                "itemStyle": {"color": "#c0392b"},
                "data": [{
                    "coord": [peak_temp, peak_value],
                    "name": f"{peak_temp:.0f} °C",
                    "label": {
                        "show": True,
                        "formatter": f"{peak_temp:.0f} °C",
                        "position": "top"
                    }
                }]
            }
        }
    ]
}

print(json.dumps({
    "figures": [{
        "name": "PET",
